(()=>{
 const q=s=>document.querySelector(s),feedback=q('#status'),form=q('#retention-form'),cloudForm=q('#cloud-retention-form'),oauth=q('#oauth-form'),dialog=q('#mode-dialog');let busy=false,snapshot=null,timer=null,mode=null;
 async function api(path='',method='GET',payload){const response=await fetch('/api/admin/archive-settings'+path,{method,cache:'no-store',headers:method==='GET'?{}:{'X-Requested-With':'KrugPi','Content-Type':'application/json'},...(payload?{body:JSON.stringify(payload)}:{})});const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'Не удалось выполнить действие.');return result;}
 function freeze(value){busy=value;document.querySelectorAll('#settings-content button,#settings-content input').forEach(node=>node.disabled=value);if(!value&&snapshot)q('#connect').disabled=!snapshot.configured;}
 function cycleStatus(prefix,data){const running=data[prefix+'_running'],stamp=data[prefix+'_last_finished'],result=data[prefix+'_result'];return running?'Выполняется цикл. Дождитесь результата…':(stamp?'Последний запуск: '+new Date(stamp*1000).toLocaleString('ru-RU')+'.':'Последний запуск: ещё не выполнялся.')+(result?' Обработано: '+result.processed+(prefix==='cloud'?', предупреждений: '+result.warned+', удалено ZIP: '+result.deleted:', очищено: '+result.cleaned)+', ошибок: '+result.errors+'.':'')}
 function render(data,forms=true){snapshot=data;
  for(const [kind,enabled] of [['server',data.deletion_enabled],['cloud',data.cloud_deletion_enabled]]){q('#'+kind+'-mode-badge').textContent=enabled?'Включена':'Выключена';q('#'+kind+'-mode-badge').classList.toggle('is-enabled',enabled);q('#'+kind+'-mode-toggle').textContent=(enabled?'Выключить':'Включить')+' автоочистку '+(kind==='server'?'сервера':'Google Диска');}
  q('#server-cycle-status').textContent=cycleStatus('cleanup',data);q('#cloud-cycle-status').textContent=cycleStatus('cloud',data);
  if(forms){oauth.elements.client_id.value=data.client_id||'';oauth.elements.redirect_uri.value=data.redirect_uri||location.origin+'/api/admin/archive-settings/callback';oauth.elements.client_secret.value='';oauth.elements.client_secret.required=!data.secret_saved;q('#secret-state').textContent=data.secret_saved?'Секрет сохранён на сервере. Оставьте поле пустым, чтобы сохранить его, или введите новый для замены.':'Введите Client Secret из Google Cloud. После сохранения он не будет отображаться.';if(!data.configured)q('#oauth-parameters').open=true;q('#drive-state').textContent=data.connected?'Подключён':'Не подключён';q('#drive-account').textContent=data.connected?'Аккаунт: '+(data.email||'Google'):'Подключите диск, на котором будут храниться архивы.';q('#connect').textContent=data.connected?'Переподключить':'Подключить Google Диск';q('#test').hidden=q('#disconnect').hidden=!data.connected;q('#drive-folder').hidden=!data.folder_id;if(data.folder_id){q('#drive-folder-link').href='https://drive.google.com/drive/folders/'+encodeURIComponent(data.folder_id);q('#drive-folder-link').textContent=data.folder_name+' →'}q('#callback-url').textContent=data.redirect_uri||oauth.elements.redirect_uri.value;q('#missing-settings').textContent=data.missing.length?'Не заданы: '+data.missing.join(', '):'Параметры подключения сохранены '+(data.config_source==='settings'?'через настройки сайта.':'в окружении сервера.');if(!data.configured)q('#setup-help').open=true;
   form.elements.retention_days.value=data.retention_days;form.elements.grace_days.value=data.grace_days;cloudForm.elements.cloud_retention_months.value=data.cloud_retention_months;cloudForm.elements.cloud_warning_days.value=data.cloud_warning_days;
  }
  q('#events-empty').hidden=!!data.events.length;q('#events').replaceChildren();for(const event of data.events){const item=document.createElement('li'),date=document.createElement('time');date.dateTime=new Date(event.at*1000).toISOString();date.textContent=new Date(event.at*1000).toLocaleString('ru-RU');item.append(date,document.createTextNode(event.message));q('#events').append(item)}
 }
 async function action(task){if(busy)return;freeze(true);feedback.textContent='Выполняем…';try{await task()}catch(error){feedback.textContent=error.message}finally{freeze(false)}}
  q('#connect').onclick=()=>action(async()=>{const result=await api('/connect','POST');location.assign(result.url)});
 q('#test').onclick=()=>action(async()=>{try{render(await api('/test','POST'));feedback.textContent='Проверка пройдена. Тестовый файл удалён.'}catch(error){try{render(await api())}catch{}throw error}});
 q('#disconnect').onclick=()=>{if(!confirm('Отключить Google Диск? Архивы в Drive сохранятся.'))return;void action(async()=>{await api('/disconnect','POST');render(await api());feedback.textContent='Подключение отключено. Файлы в Google Drive сохранены.'})};
 oauth.onsubmit=event=>{event.preventDefault();if(snapshot?.connected&&!confirm('Сохранить параметры Google? Если они изменились, потребуется заново подключить диск. Архивы сохранятся.'))return;void action(async()=>{const payload={client_id:oauth.elements.client_id.value.trim(),redirect_uri:oauth.elements.redirect_uri.value.trim()};const secret=oauth.elements.client_secret.value.trim();if(secret)payload.client_secret=secret;render(await api('/oauth-config','PUT',payload));feedback.textContent='Параметры сохранены. Нажмите «Подключить Google Диск», если подключение ещё не выполнено.'})};

 form.onsubmit=event=>{event.preventDefault();void action(async()=>{render(await api('','PUT',{retention_days:Number(form.elements.retention_days.value),grace_days:Number(form.elements.grace_days.value)}),false);feedback.textContent='Сроки сервера сохранены. Режим автоочистки не изменён.'})};
 cloudForm.onsubmit=event=>{event.preventDefault();void action(async()=>{render(await api('/cloud-retention','PUT',{cloud_retention_months:Number(cloudForm.elements.cloud_retention_months.value),cloud_warning_days:Number(cloudForm.elements.cloud_warning_days.value)}),false);feedback.textContent='Сроки Google Диска сохранены. Режим автоочистки не изменён.'})};
 function openMode(kind){if(busy||!snapshot)return;const enabled=!(kind==='server'?snapshot.deletion_enabled:snapshot.cloud_deletion_enabled);mode={kind,enabled};q('#mode-title').textContent=(enabled?'Включить':'Выключить')+' автоочистку '+(kind==='server'?'сервера?':'Google Диска?');q('#mode-message').textContent=!enabled?'Будущие автоматические операции этого режима будут остановлены. Уже начатая операция может завершиться. Второй режим и ручные действия не изменятся.':kind==='server'?'После проверки ZIP, уведомления ученика, срока хранения исходников ('+snapshot.retention_days+' дней) и ожидания ('+snapshot.grace_days+' дней) вложения будут автоматически удаляться с сервера. ZIP на Google Диске, тексты и история занятий сохранятся.':'ZIP будут удаляться безвозвратно через '+snapshot.cloud_retention_months+' календарных месяцев после проверки. Сначала предупреждение на подтверждённую почту ученика и не менее '+snapshot.cloud_warning_days+' дней ожидания — также для старых архивов. Если письмо не отправлено, удаление откладывается. Скачивание удалённого ZIP станет недоступным. Тексты, история и имеющиеся исходники сохранятся.';q('#mode-confirm').textContent=enabled?'Включить':'Выключить';q('#mode-confirm').hidden=false;q('#mode-cancel').textContent='Отмена';dialog.showModal();q('#mode-cancel').focus()}
 q('#server-mode-toggle').onclick=()=>openMode('server');q('#cloud-mode-toggle').onclick=()=>openMode('cloud');q('#mode-cancel').onclick=()=>dialog.close();dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault()});
 q('#mode-confirm').onclick=async()=>{if(busy||!mode)return;freeze(true);q('#mode-confirm').disabled=q('#mode-cancel').disabled=true;try{const data=await api(mode.kind==='server'?'/cleanup-mode':'/cloud-cleanup-mode','POST',{enabled:mode.enabled,confirmed:true});render(data,false);q('#mode-title').textContent='Режим '+(mode.enabled?'включён':'выключен');q('#mode-message').textContent='Настройка сохранена. Второй режим не изменён. Результаты работы будут обновляться автоматически.';q('#mode-confirm').hidden=true;q('#mode-cancel').textContent='Готово';feedback.textContent='Режим сохранён.'}catch(error){q('#mode-message').textContent=error.message}finally{freeze(false);q('#mode-confirm').disabled=q('#mode-cancel').disabled=false;q('#mode-cancel').focus()}};
 async function poll(){if(!snapshot||busy||dialog.open||document.hidden)return;try{render(await api(),false)}catch{feedback.textContent='Не удалось обновить статус. Повторим автоматически.'}}
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)void poll()});window.addEventListener('pagehide',()=>clearInterval(timer));window.addEventListener('pageshow',()=>{clearInterval(timer);timer=setInterval(()=>void poll(),15000)});
 (async()=>{try{render(await api());window.mountAdminNavigation('settings');q('#settings-content').hidden=false;const result=new URLSearchParams(location.search).get('connection');feedback.textContent=result==='connected'?'Google Диск подключён. Выполните проверку.':result==='invalid'?'Ссылка подключения истекла или открыта в другом сеансе. Повторите подключение.':result==='failed'?'Не удалось подключить Google Диск. Проверьте настройки и журнал.':'';if(result)history.replaceState(null,'',location.pathname);clearInterval(timer);timer=setInterval(()=>void poll(),15000)}catch(error){feedback.textContent=error.message}})();
})();
